"""Plots of the worst bounce (diagnostic only): reads data/diag/bounce_20261029/ticks.csv, writes two PNGs beside it.

    python experiments/bounce_diag_plot.py
"""

import sys
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import pandas as pd  # noqa: E402

HERE = Path(__file__).resolve().parent.parent / "data" / "diag" / "bounce_20261029"
BLUE, ORANGE, AQUA = "#2a78d6", "#eb6834", "#1baf7a"            # reference palette, categorical slots 1-3 (light)
INK, MUTED = "#0b0b0b", "#52514e"
HZ = 150.0
LO, HI = 11336, 11936                                            # +-2 s around the peak at tick 11636 (video 1:23)
MARKS = {11599: "comp on", 11601: "PLACE start", 11636: "peak 3.4 deg", 11646: "target jump", 11856: "OVER->DOWN handover"}


def style(ax, ylabel):
    ax.set_ylabel(ylabel, color=INK)
    ax.tick_params(colors=MUTED)
    for s in ("top", "right"):
        ax.spines[s].set_visible(False)
    for t, lab in MARKS.items():
        if LO <= t <= HI:
            ax.axvline(t, color=MUTED, lw=0.6, ls=":")


def main():
    df = pd.read_csv(HERE / "ticks.csv")
    w = df[(df.tick >= LO) & (df.tick <= HI)].copy()
    t = w.tick.values
    fig, ax = plt.subplots(4, 1, figsize=(10, 11), sharex=True)

    ax[0].plot(t, w.tilt, color=INK, lw=1.4, label="beaker tilt")
    style(ax[0], "beaker tilt (deg)")
    ax[0].legend(frameon=False, loc="upper left", fontsize=8)
    ax[0].set_title("Worst bounce, blend20 run (video 1:23 = tick 11636); held comp switches on at tick 11599", color=INK, fontsize=10, loc="left")

    for j, c in (("L7", BLUE), ("L1", ORANGE), ("L4", AQUA)):
        ax[1].plot(t, 1000 * (w[f"{j}_q"] - w[f"{j}_tgt"]), color=c, lw=1.2, label=f"{j} sag = measured - target")
    style(ax[1], "joint sag (mrad)")
    ax[1].axhline(0, color=MUTED, lw=0.5)
    ax[1].legend(frameon=False, loc="upper left", fontsize=8)

    for j, c in (("L7", BLUE), ("L1", ORANGE), ("L4", AQUA)):
        ax[2].plot(t, w[f"{j}_ff_held"], color=c, lw=1.2, label=f"{j} held-object torque (ff_held)")
    style(ax[2], "held torque (N m)")
    ax[2].axhline(0, color=MUTED, lw=0.5)
    ax[2].legend(frameon=False, loc="upper left", fontsize=8)

    for j, c in (("L7", BLUE), ("L4", ORANGE)):
        ax[3].plot(t, w[f"{j}_tgt"].diff() * HZ, color=c, lw=1.2, ls="--", label=f"{j} commanded velocity (skill target)")
        ax[3].plot(t, w[f"{j}_qd"], color=c, lw=1.6, label=f"{j} measured velocity")
    style(ax[3], "joint velocity (rad/s)")
    ax[3].axhline(0, color=MUTED, lw=0.5)
    ax[3].legend(frameon=False, loc="upper left", fontsize=8)
    ax[3].set_xlabel("control tick (150 Hz; video 1:23 = tick 11636)", color=INK)
    for tk, lab in MARKS.items():
        if LO <= tk <= HI:
            ax[0].annotate(lab, (tk, ax[0].get_ylim()[1]), fontsize=7, color=MUTED, rotation=90, va="top", ha="right")

    fig.tight_layout()
    out = HERE / "bounce_1_23_signals.png"
    fig.savefig(out, dpi=120)
    print("wrote", out)


if __name__ == "__main__":
    sys.exit(main())
